package main
import("encoding/json";"fmt";"os";"strings";"time";bolt "go.etcd.io/bbolt")
func main(){if len(os.Args)!=2{panic("one explicit read-only DB path required")};db,err:=bolt.Open(os.Args[1],0400,&bolt.Options{ReadOnly:true,Timeout:2*time.Second});if err!=nil{panic(err)};defer db.Close();cve:="CVE-2026-111142";rows:=[]map[string]any{};buckets:=[]string{};var detail json.RawMessage
err=db.View(func(tx *bolt.Tx)error{return tx.ForEach(func(name []byte,b *bolt.Bucket)error{bucket:=string(name);buckets=append(buckets,bucket);if bucket=="vulnerability"{value:=b.Get([]byte(cve));if value!=nil{detail=append([]byte{},value...)}}
if strings.HasPrefix(strings.ToLower(bucket),"debian"){pkg:=b.Bucket([]byte("zziplib"));row:=map[string]any{"sourceBucket":bucket,"packageBucketPresent":pkg!=nil,"requestedAdvisoryPresent":false};ids:=[]string{};if pkg!=nil{if err:=pkg.ForEach(func(k,v []byte)error{if len(ids)>=1000{return fmt.Errorf("package advisory bound")};ids=append(ids,string(k));if string(k)==cve{row["requestedAdvisoryPresent"]=true;row["advisory"]=json.RawMessage(append([]byte{},v...))};return nil});err!=nil{return err}};row["advisoryIds"]=ids;rows=append(rows,row)};if len(buckets)>2000{return fmt.Errorf("source bucket bound")};return nil})});if err!=nil{panic(err)};result:=map[string]any{"scope":"read-only exact published DB query; no writes or coverage waiver","requestedId":cve,"globalVulnerabilityRecordPresent":detail!=nil,"globalVulnerabilityRecord":detail,"sourceBuckets":buckets,"debianZziplib":rows};encoded,err:=json.MarshalIndent(result,"","  ");if err!=nil{panic(err)};fmt.Println(string(encoded))}
